import{_ as i,c as o,o as r,a3 as a}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Invoicing","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/invoicing/index.md","filePath":"master/sales/sales/invoicing/index.md","lastUpdated":1791902625000}'),t={name:"master/sales/sales/invoicing/index.md"};function n(s,e,l,c,d,h){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="invoicing" tabindex="-1">Invoicing <a class="header-anchor" href="#invoicing" aria-label="Permalink to &quot;Invoicing&quot;">​</a></h1><p>Invoicing turns a confirmed sales order into a customer invoice. The <strong>To Invoice</strong> menu lists the orders that still need invoicing, and the invoice policy decides when an order is ready for it.</p><blockquote><p><strong>In simple words:</strong> Confirm the order, then invoice it from the <strong>To Invoice</strong> menu.</p></blockquote><h2 id="how-an-order-reaches-an-invoice" tabindex="-1">How an order reaches an invoice <a class="header-anchor" href="#how-an-order-reaches-an-invoice" aria-label="Permalink to &quot;How an order reaches an invoice&quot;">​</a></h2><ol><li>Create and confirm a quotation. It becomes a sales order. See <a href="./../quotations-orders/send-and-confirm-quotation.html">Send and confirm a quotation</a>.</li><li>The invoice policy decides when the order is ready to invoice. See <a href="./invoicing-policies.html">Invoicing policies</a>.</li><li>Open the order and click <strong>Create Invoice</strong>. See <a href="./order-to-invoice.html">Orders to invoice</a>.</li><li>The invoice is created for the customer.</li></ol><h2 id="the-two-lists" tabindex="-1">The two lists <a class="header-anchor" href="#the-two-lists" aria-label="Permalink to &quot;The two lists&quot;">​</a></h2><p>The <strong>To Invoice</strong> menu has two pages. Both list sales orders, filtered by their invoice status.</p><ul><li><strong>Orders To Invoice:</strong> Orders that are ready to be invoiced.</li><li><strong>Orders To Upsell:</strong> Orders where the invoice status is <strong>Up Selling</strong>.</li></ul><h2 id="in-this-group" tabindex="-1">In this group <a class="header-anchor" href="#in-this-group" aria-label="Permalink to &quot;In this group&quot;">​</a></h2><ul><li><a href="./invoicing-policies.html">Invoicing policies</a></li><li><a href="./order-to-invoice.html">Orders to invoice</a></li><li><a href="./order-to-upsell.html">Orders to upsell</a></li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../quotations-orders/manage-orders.html">Manage orders</a></li><li><a href="./../configuration/settings.html">Sales settings</a></li></ul>',12)]))}const m=i(t,[["render",n]]);export{g as __pageData,m as default};
